#!/usr/bin/env node
'use strict';

const fs = require('node:fs');
const path = require('node:path');

// Notes live next to this script. NOTES_FILE can override the path (used by tests
// so they never touch the real notes.json).
function notesPath() {
  return process.env.NOTES_FILE || path.join(__dirname, 'notes.json');
}

function loadNotes(file = notesPath()) {
  let raw;
  try {
    raw = fs.readFileSync(file, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }
  if (raw.trim() === '') return [];
  let data;
  try {
    data = JSON.parse(raw);
  } catch {
    throw new Error(`${file} is not valid JSON; fix or remove it.`);
  }
  if (!Array.isArray(data)) {
    throw new Error(`${file} must contain a JSON array of notes.`);
  }
  return data;
}

function saveNotes(notes, file = notesPath()) {
  // Write to a temp file and rename, so a crash mid-write can't corrupt notes.json.
  const tmp = `${file}.${process.pid}.tmp`;
  fs.writeFileSync(tmp, JSON.stringify(notes, null, 2) + '\n');
  fs.renameSync(tmp, file);
}

function addNote(text, file = notesPath()) {
  if (typeof text !== 'string' || text.trim() === '') {
    throw new Error('Note text cannot be empty.');
  }
  const notes = loadNotes(file);
  const id = notes.reduce((max, n) => Math.max(max, n.id), 0) + 1;
  const note = { id, text, createdAt: new Date().toISOString() };
  notes.push(note);
  saveNotes(notes, file);
  return note;
}

function listNotes(file = notesPath()) {
  return loadNotes(file);
}

function deleteNote(id, file = notesPath()) {
  const notes = loadNotes(file);
  const index = notes.findIndex((n) => n.id === id);
  if (index === -1) return null;
  const [removed] = notes.splice(index, 1);
  saveNotes(notes, file);
  return removed;
}

const USAGE = `Usage:
  node notes.js add "text"    Add a note
  node notes.js list          List all notes
  node notes.js delete <id>   Delete a note by id`;

function main(argv) {
  const [command, ...args] = argv;

  switch (command) {
    case 'add': {
      const text = args.join(' ');
      if (text.trim() === '') {
        console.error('Error: note text is required.\n' + USAGE);
        return 1;
      }
      const note = addNote(text);
      console.log(`Added note ${note.id}: ${note.text}`);
      return 0;
    }
    case 'list': {
      const notes = listNotes();
      if (notes.length === 0) {
        console.log('No notes.');
      } else {
        for (const n of notes) console.log(`${n.id}: ${n.text}`);
      }
      return 0;
    }
    case 'delete': {
      const raw = args[0];
      if (raw === undefined || !/^\d+$/.test(raw)) {
        console.error('Error: delete needs a numeric id.\n' + USAGE);
        return 1;
      }
      const id = Number(raw);
      const removed = deleteNote(id);
      if (!removed) {
        console.error(`Error: no note with id ${id}.`);
        return 1;
      }
      console.log(`Deleted note ${id}.`);
      return 0;
    }
    case undefined:
    case 'help':
    case '--help':
    case '-h':
      console.log(USAGE);
      return command === undefined ? 1 : 0;
    default:
      console.error(`Error: unknown command "${command}".\n` + USAGE);
      return 1;
  }
}

if (require.main === module) {
  try {
    process.exitCode = main(process.argv.slice(2));
  } catch (err) {
    console.error(`Error: ${err.message}`);
    process.exitCode = 1;
  }
}

module.exports = { addNote, listNotes, deleteNote, loadNotes, saveNotes, notesPath, main };

