'use strict';

const { test, beforeEach, afterEach } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { spawnSync } = require('node:child_process');

const {
  addNote,
  listNotes,
  searchNotes,
  deleteNote,
  notesPath,
  normalizeTags,
  parseAddArgs,
  formatNote,
} = require('./notes.js');

const SCRIPT = path.join(__dirname, 'notes.js');
let dir;
let file;

beforeEach(() => {
  dir = fs.mkdtempSync(path.join(os.tmpdir(), 'notes-test-'));
  file = path.join(dir, 'notes.json');
});

afterEach(() => {
  fs.rmSync(dir, { recursive: true, force: true });
});

function run(...args) {
  const result = spawnSync(process.execPath, [SCRIPT, ...args], {
    env: { ...process.env, NOTES_FILE: file },
    encoding: 'utf8',
  });
  return { code: result.status, stdout: result.stdout, stderr: result.stderr };
}

// --- module API: core ---

test('default storage path is notes.json next to the script', () => {
  const saved = process.env.NOTES_FILE;
  delete process.env.NOTES_FILE;
  try {
    assert.equal(notesPath(), path.join(__dirname, 'notes.json'));
  } finally {
    if (saved !== undefined) process.env.NOTES_FILE = saved;
  }
});

test('listNotes returns [] when the file does not exist', () => {
  assert.deepEqual(listNotes(file), []);
});

test('addNote assigns incrementing ids and persists to disk', () => {
  const a = addNote('first', [], file);
  const b = addNote('second', [], file);
  assert.equal(a.id, 1);
  assert.equal(b.id, 2);
  const onDisk = JSON.parse(fs.readFileSync(file, 'utf8'));
  assert.deepEqual(onDisk.map((n) => [n.id, n.text]), [[1, 'first'], [2, 'second']]);
});

test('addNote rejects empty text', () => {
  assert.throws(() => addNote('   ', [], file), /empty/);
  assert.equal(fs.existsSync(file), false);
});

test('new ids come after the highest existing id, so they never collide', () => {
  addNote('a', [], file);
  addNote('b', [], file);
  addNote('c', [], file);
  deleteNote(2, file);
  const d = addNote('d', [], file);
  assert.equal(d.id, 4);
  assert.deepEqual(listNotes(file).map((n) => n.id), [1, 3, 4]);
});

test('deleteNote removes the note and returns it; returns null if missing', () => {
  addNote('keep', [], file);
  addNote('drop', [], file);
  const removed = deleteNote(2, file);
  assert.equal(removed.text, 'drop');
  assert.deepEqual(listNotes(file).map((n) => n.text), ['keep']);
  assert.equal(deleteNote(99, file), null);
});

test('loadNotes reports corrupt JSON clearly', () => {
  fs.writeFileSync(file, '{not json');
  assert.throws(() => listNotes(file), /not valid JSON/);
});

// --- module API: tags ---

test('addNote stores tags; defaults to no tags', () => {
  const tagged = addNote('plan', ['work', 'idea'], file);
  const plain = addNote('plain', undefined, file);
  assert.deepEqual(tagged.tags, ['work', 'idea']);
  assert.deepEqual(plain.tags, []);
  const onDisk = JSON.parse(fs.readFileSync(file, 'utf8'));
  assert.deepEqual(onDisk.map((n) => n.tags), [['work', 'idea'], []]);
});

test('normalizeTags trims, drops blanks, and dedupes case-insensitively', () => {
  assert.deepEqual(normalizeTags([' work ', 'Idea', 'idea', '', '  ', 'WORK', 'home']), [
    'work',
    'Idea',
    'home',
  ]);
  assert.throws(() => normalizeTags('work'), /array/);
  assert.throws(() => normalizeTags([1]), /array/);
});

test('formatNote shows tags in brackets only when present', () => {
  assert.equal(formatNote({ id: 1, text: 'a', tags: [] }), '1: a');
  assert.equal(formatNote({ id: 2, text: 'b' }), '2: b');
  assert.equal(formatNote({ id: 3, text: 'c', tags: ['x', 'y'] }), '3: c [x, y]');
});

test('parseAddArgs separates text from --tag options', () => {
  assert.deepEqual(parseAddArgs(['buy', 'milk', '--tag', 'home', '--tag=errand']), {
    text: 'buy milk',
    tags: ['home', 'errand'],
  });
  // Tags may come before, between, or after the text.
  assert.deepEqual(parseAddArgs(['--tag', 'a', 'hello', '--tag', 'b', 'world']), {
    text: 'hello world',
    tags: ['a', 'b'],
  });
  // Everything after `--` is literal text.
  assert.deepEqual(parseAddArgs(['--tag', 'meta', '--', 'use', '--tag', 'flag']), {
    text: 'use --tag flag',
    tags: ['meta'],
  });
});

test('parseAddArgs rejects a missing tag value and unknown options', () => {
  assert.throws(() => parseAddArgs(['text', '--tag']), /--tag needs a value/);
  assert.throws(() => parseAddArgs(['text', '--tag', '--tag', 'x']), /--tag needs a value/);
  assert.throws(() => parseAddArgs(['text', '--tag=']), /--tag needs a value/);
  assert.throws(() => parseAddArgs(['text', '--tga', 'x']), /unknown option "--tga"/);
});

// --- module API: search ---

test('searchNotes matches text and tags, case-insensitively', () => {
  addNote('Quarterly report draft', ['work'], file); // 1
  addNote('Buy milk', ['home', 'errand'], file); // 2
  addNote('App idea: notes sync', ['Ideas'], file); // 3
  addNote('Call the plumber', [], file); // 4

  const ids = (q) => searchNotes(q, file).map((n) => n.id);
  assert.deepEqual(ids('report'), [1]); // text
  assert.deepEqual(ids('REPORT'), [1]); // case-insensitive text
  assert.deepEqual(ids('errand'), [2]); // tag
  assert.deepEqual(ids('idea'), [3]); // text "idea" and tag "Ideas"
  assert.deepEqual(ids('work'), [1]); // tag only
  assert.deepEqual(ids('o'), [1, 2, 3]); // substring across text/tags, in order
  assert.deepEqual(ids('zebra'), []);
});

test('searchNotes does not return a note twice when text and tag both match', () => {
  addNote('work stuff', ['work'], file);
  assert.equal(searchNotes('work', file).length, 1);
});

test('searchNotes handles notes saved before tags existed', () => {
  fs.writeFileSync(file, JSON.stringify([{ id: 1, text: 'legacy note', createdAt: 'x' }]));
  assert.deepEqual(searchNotes('legacy', file).map((n) => n.id), [1]);
  assert.deepEqual(searchNotes('work', file), []);
});

test('searchNotes rejects an empty query', () => {
  assert.throws(() => searchNotes('  ', file), /empty/);
});

// --- CLI: core ---

