  const result = spawnSync(process.execPath, [SCRIPT, ...args], {
    env: { ...process.env, NOTES_FILE: file },
    encoding: 'utf8',
  });
  return { code: result.status, stdout: result.stdout, stderr: result.stderr };
}

// --- module API: core ---

test('default storage path is notes.json next to the script', () => {
  const saved = process.env.NOTES_FILE;
  delete process.env.NOTES_FILE;
  try {
    assert.equal(notesPath(), path.join(__dirname, 'notes.json'));
  } finally {
    if (saved !== undefined) process.env.NOTES_FILE = saved;
  }
});

test('listNotes returns [] when the file does not exist', () => {
