});

test('normalizeTags trims, drops blanks, and dedupes case-insensitively', () => {
  assert.deepEqual(normalizeTags([' work ', 'Idea', 'idea', '', '  ', 'WORK', 'home']), [
    'work',
    'Idea',
    'home',
  ]);
