  assert.equal(formatNote({ id: 1, text: 'a', tags: [] }), '1: a');
  assert.equal(formatNote({ id: 2, text: 'b' }), '2: b');
  assert.equal(formatNote({ id: 3, text: 'c', tags: ['x', 'y'] }), '3: c [x, y]');
