    text: 'buy milk',
    tags: ['home', 'errand'],
  });
  // Tags may come before, between, or after the text.
  assert.deepEqual(parseAddArgs(['--tag', 'a', 'hello', '--tag', 'b', 'world']), {
    text: 'hello world',
    tags: ['a', 'b'],
  });
  // Everything after `--` is literal text.
  assert.deepEqual(parseAddArgs(['--tag', 'meta', '--', 'use', '--tag', 'flag']), {
    text: 'use --tag flag',
    tags: ['meta'],
  });
});

test('parseAddArgs rejects a missing tag value and unknown options', () => {
  assert.throws(() => parseAddArgs(['text', '--tag']), /--tag needs a value/);
  assert.throws(() => parseAddArgs(['text', '--tag', '--tag', 'x']), /--tag needs a value/);
  assert.throws(() => parseAddArgs(['text', '--tag=']), /--tag needs a value/);
  assert.throws(() => parseAddArgs(['text', '--tga', 'x']), /unknown option "--tga"/);
