  for (const bad of [[], ['abc'], ['1.5'], ['-1']]) {
    const r = run('delete', ...bad);
    assert.equal(r.code, 1, `expected failure for ${JSON.stringify(bad)}`);
    assert.match(r.stderr, /numeric id/);
  }
});

test('CLI: unknown command fails with usage', () => {
  const r = run('frobnicate');
  assert.equal(r.code, 1);
  assert.match(r.stderr, /unknown command/);
  assert.match(r.stderr, /Usage:/);
});

test('CLI: corrupt notes.json gives an error, not a stack trace', () => {
  fs.writeFileSync(file, '[[[');
  const r = run('list');
  assert.equal(r.code, 1);
  assert.match(r.stderr, /^Error: .*not valid JSON/);
});

