test('CLI: add with --tag stores tags and list shows them', () => {
  let r = run('add', 'ship the feature', '--tag', 'work', '--tag', 'idea');
  assert.equal(r.code, 0);
  assert.equal(r.stdout, 'Added note 1: ship the feature [work, idea]\n');

  run('add', 'untagged');

  assert.deepEqual(listNotes(file)[0].tags, ['work', 'idea']);
  r = run('list');
  assert.equal(r.stdout, '1: ship the feature [work, idea]\n2: untagged\n');
});

test('CLI: add with only tags and no text fails without saving', () => {
  const r = run('add', '--tag', 'work');
  assert.equal(r.code, 1);
  assert.match(r.stderr, /text is required/);
  assert.equal(fs.existsSync(file), false);
});

test('CLI: add with a dangling --tag fails without saving', () => {
  const r = run('add', 'text', '--tag');
  assert.equal(r.code, 1);
  assert.match(r.stderr, /--tag needs a value/);
