  r = run('search', 'work');
  assert.equal(r.stdout, '1: Quarterly report [work]\n3: Homework for Sam\n');

  // "HOME" matches note 2's tag and note 3's text, case-insensitively.
  r = run('search', 'HOME');
  assert.equal(r.stdout, '2: Buy milk [home]\n3: Homework for Sam\n');
});

