  assert.equal(r.code, 0);
  assert.equal(r.stdout, 'No matching notes.\n');
});

test('CLI: search on an empty store', () => {
  const r = run('search', 'anything');
  assert.equal(r.code, 0);
  assert.equal(r.stdout, 'No matching notes.\n');
});

test('CLI: search without a word fails', () => {
  const r = run('search');
  assert.equal(r.code, 1);
  assert.match(r.stderr, /search needs a word/);
});

