'use strict';

const { test, beforeEach, afterEach } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { spawnSync } = require('node:child_process');

const { addNote, listNotes, deleteNote, notesPath } = require('./notes.js');

const SCRIPT = path.join(__dirname, 'notes.js');
let dir;
let file;

beforeEach(() => {
  dir = fs.mkdtempSync(path.join(os.tmpdir(), 'notes-test-'));
  file = path.join(dir, 'notes.json');
});

afterEach(() => {
  fs.rmSync(dir, { recursive: true, force: true });
});

function run(...args) {
  const result = spawnSync(process.execPath, [SCRIPT, ...args], {
    env: { ...process.env, NOTES_FILE: file },
    encoding: 'utf8',
  });
  return { code: result.status, stdout: result.stdout, stderr: result.stderr };
}

// --- module API ---

test('default storage path is notes.json next to the script', () => {
  const saved = process.env.NOTES_FILE;
  delete process.env.NOTES_FILE;
  try {
    assert.equal(notesPath(), path.join(__dirname, 'notes.json'));
  } finally {
    if (saved !== undefined) process.env.NOTES_FILE = saved;
  }
});

test('listNotes returns [] when the file does not exist', () => {
  assert.deepEqual(listNotes(file), []);
});

test('addNote assigns incrementing ids and persists to disk', () => {
  const a = addNote('first', file);
  const b = addNote('second', file);
  assert.equal(a.id, 1);
  assert.equal(b.id, 2);
  const onDisk = JSON.parse(fs.readFileSync(file, 'utf8'));
  assert.deepEqual(onDisk.map((n) => [n.id, n.text]), [[1, 'first'], [2, 'second']]);
});

test('addNote rejects empty text', () => {
  assert.throws(() => addNote('   ', file), /empty/);
  assert.equal(fs.existsSync(file), false);
});

test('new ids come after the highest existing id, so they never collide', () => {
  addNote('a', file);
  addNote('b', file);
  addNote('c', file);
  deleteNote(2, file);
  const d = addNote('d', file);
  assert.equal(d.id, 4);
  assert.deepEqual(listNotes(file).map((n) => n.id), [1, 3, 4]);
});

test('deleteNote removes the note and returns it; returns null if missing', () => {
  addNote('keep', file);
  addNote('drop', file);
  const removed = deleteNote(2, file);
  assert.equal(removed.text, 'drop');
  assert.deepEqual(listNotes(file).map((n) => n.text), ['keep']);
  assert.equal(deleteNote(99, file), null);
});

test('loadNotes reports corrupt JSON clearly', () => {
  fs.writeFileSync(file, '{not json');
  assert.throws(() => listNotes(file), /not valid JSON/);
});

// --- CLI ---

test('CLI: add, list, delete round trip', () => {
  let r = run('add', 'buy milk');
  assert.equal(r.code, 0);
  assert.match(r.stdout, /Added note 1: buy milk/);

  r = run('add', 'call mom');
  assert.equal(r.code, 0);

  r = run('list');
  assert.equal(r.code, 0);
  assert.equal(r.stdout, '1: buy milk\n2: call mom\n');

  r = run('delete', '1');
  assert.equal(r.code, 0);
  assert.match(r.stdout, /Deleted note 1/);

  r = run('list');
  assert.equal(r.stdout, '2: call mom\n');
});

test('CLI: list with no notes', () => {
  const r = run('list');
  assert.equal(r.code, 0);
  assert.equal(r.stdout, 'No notes.\n');
});

test('CLI: add preserves quotes and special characters', () => {
  const text = 'say "hi" & <bye> — ünïcödé';
  assert.equal(run('add', text).code, 0);
  assert.equal(listNotes(file)[0].text, text);
});

test('CLI: add without text fails', () => {
  const r = run('add');
  assert.equal(r.code, 1);
  assert.match(r.stderr, /text is required/);
});

test('CLI: delete with unknown id fails', () => {
  run('add', 'x');
  const r = run('delete', '42');
  assert.equal(r.code, 1);
  assert.match(r.stderr, /no note with id 42/);
  assert.equal(listNotes(file).length, 1);
});

test('CLI: delete with non-numeric id fails', () => {
  for (const bad of [[], ['abc'], ['1.5'], ['-1']]) {
    const r = run('delete', ...bad);
    assert.equal(r.code, 1, `expected failure for ${JSON.stringify(bad)}`);
    assert.match(r.stderr, /numeric id/);
  }
});

test('CLI: unknown command fails with usage', () => {
  const r = run('frobnicate');
  assert.equal(r.code, 1);
  assert.match(r.stderr, /unknown command/);
  assert.match(r.stderr, /Usage:/);
});

test('CLI: corrupt notes.json gives an error, not a stack trace', () => {
  fs.writeFileSync(file, '[[[');
  const r = run('list');
  assert.equal(r.code, 1);
  assert.match(r.stderr, /^Error: .*not valid JSON/);
});

