#!/usr/bin/env node
'use strict';

const fs = require('node:fs');
const path = require('node:path');

// Notes live next to this script. NOTES_FILE can override the path (used by tests
// so they never touch the real notes.json).
function notesPath() {
  return process.env.NOTES_FILE || path.join(__dirname, 'notes.json');
}

function loadNotes(file = notesPath()) {
  let raw;
  try {
    raw = fs.readFileSync(file, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }
  if (raw.trim() === '') return [];
  let data;
  try {
    data = JSON.parse(raw);
  } catch {
    throw new Error(`${file} is not valid JSON; fix or remove it.`);
  }
  if (!Array.isArray(data)) {
    throw new Error(`${file} must contain a JSON array of notes.`);
  }
  return data;
}

function saveNotes(notes, file = notesPath()) {
  // Write to a temp file and rename, so a crash mid-write can't corrupt notes.json.
  const tmp = `${file}.${process.pid}.tmp`;
  fs.writeFileSync(tmp, JSON.stringify(notes, null, 2) + '\n');
  fs.renameSync(tmp, file);
}

// Trim tags, drop empty ones, and remove duplicates (case-insensitively,
// keeping the first spelling given).
function normalizeTags(tags) {
  if (!Array.isArray(tags)) throw new Error('Tags must be an array of strings.');
  const seen = new Set();
  const result = [];
  for (const tag of tags) {
    if (typeof tag !== 'string') throw new Error('Tags must be an array of strings.');
    const t = tag.trim();
    if (t === '' || seen.has(t.toLowerCase())) continue;
    seen.add(t.toLowerCase());
    result.push(t);
  }
  return result;
}

function addNote(text, tags = [], file = notesPath()) {
  if (typeof text !== 'string' || text.trim() === '') {
    throw new Error('Note text cannot be empty.');
  }
  const cleanTags = normalizeTags(tags);
  const notes = loadNotes(file);
  const id = notes.reduce((max, n) => Math.max(max, n.id), 0) + 1;
  const note = { id, text, tags: cleanTags, createdAt: new Date().toISOString() };
  notes.push(note);
  saveNotes(notes, file);
  return note;
}

function listNotes(file = notesPath()) {
  return loadNotes(file);
}

// Case-insensitive substring match against a note's text and each of its tags.
// Notes saved before tags existed have no `tags` field and are treated as untagged.
function searchNotes(query, file = notesPath()) {
  if (typeof query !== 'string' || query.trim() === '') {
    throw new Error('Search term cannot be empty.');
  }
  const q = query.trim().toLowerCase();
  return loadNotes(file).filter(
    (n) =>
      String(n.text).toLowerCase().includes(q) ||
      (n.tags || []).some((t) => t.toLowerCase().includes(q))
  );
}

function formatNote(n) {
  const tags = n.tags && n.tags.length ? ` [${n.tags.join(', ')}]` : '';
  return `${n.id}: ${n.text}${tags}`;
}

// Split `add` arguments into note text and tags. Accepts `--tag x` and `--tag=x`;
// anything after a bare `--` is treated as text, so notes can contain "--tag".
function parseAddArgs(args) {
  const words = [];
  const tags = [];
  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg === '--') {
      words.push(...args.slice(i + 1));
      break;
    }
    if (arg === '--tag') {
      const value = args[i + 1];
      if (value === undefined || value.startsWith('--') || value.trim() === '') {
        throw new UsageError('--tag needs a value.');
      }
      tags.push(value);
      i++;
    } else if (arg.startsWith('--tag=')) {
      const value = arg.slice('--tag='.length);
      if (value.trim() === '') throw new UsageError('--tag needs a value.');
      tags.push(value);
    } else if (arg.startsWith('--')) {
      throw new UsageError(`unknown option "${arg}".`);
    } else {
      words.push(arg);
    }
  }
  return { text: words.join(' '), tags };
}

class UsageError extends Error {}

function deleteNote(id, file = notesPath()) {
  const notes = loadNotes(file);
  const index = notes.findIndex((n) => n.id === id);
  if (index === -1) return null;
  const [removed] = notes.splice(index, 1);
  saveNotes(notes, file);
  return removed;
}

const USAGE = `Usage:
  node notes.js add "text" [--tag <tag>]...   Add a note, optionally tagged
  node notes.js list                          List all notes
  node notes.js search <word>                 Find notes whose text or tags contain <word>
  node notes.js delete <id>                   Delete a note by id`;

function main(argv) {
  const [command, ...args] = argv;

  switch (command) {
    case 'add': {
      let parsed;
      try {
        parsed = parseAddArgs(args);
      } catch (err) {
        if (!(err instanceof UsageError)) throw err;
        console.error(`Error: ${err.message}\n` + USAGE);
        return 1;
      }
      if (parsed.text.trim() === '') {
        console.error('Error: note text is required.\n' + USAGE);
        return 1;
      }
      const note = addNote(parsed.text, parsed.tags);
      console.log(`Added note ${formatNote(note)}`);
      return 0;
    }
    case 'list': {
      const notes = listNotes();
      if (notes.length === 0) {
        console.log('No notes.');
      } else {
        for (const n of notes) console.log(formatNote(n));
      }
      return 0;
    }
    case 'search': {
      const query = args.join(' ');
      if (query.trim() === '') {
        console.error('Error: search needs a word.\n' + USAGE);
        return 1;
      }
      const matches = searchNotes(query);
      if (matches.length === 0) {
        console.log('No matching notes.');
      } else {
        for (const n of matches) console.log(formatNote(n));
      }
      return 0;
    }
    case 'delete': {
      const raw = args[0];
      if (raw === undefined || !/^\d+$/.test(raw)) {
        console.error('Error: delete needs a numeric id.\n' + USAGE);
        return 1;
      }
      const id = Number(raw);
      const removed = deleteNote(id);
      if (!removed) {
        console.error(`Error: no note with id ${id}.`);
        return 1;
      }
      console.log(`Deleted note ${id}.`);
      return 0;
    }
    case undefined:
    case 'help':
    case '--help':
    case '-h':
      console.log(USAGE);
      return command === undefined ? 1 : 0;
    default:
      console.error(`Error: unknown command "${command}".\n` + USAGE);
      return 1;
  }
}

if (require.main === module) {
  try {
    process.exitCode = main(process.argv.slice(2));
  } catch (err) {
    console.error(`Error: ${err.message}`);
    process.exitCode = 1;
  }
}

module.exports = {
  addNote,
  listNotes,
  searchNotes,
  deleteNote,
  loadNotes,
  saveNotes,
  notesPath,
  normalizeTags,
  parseAddArgs,
  formatNote,
  main,
};

