// add / list / search / delete logic on top of it. No CLI concerns here.

const fs = require('node:fs');
const path = require('node:path');

// Notes live in notes.json in the project root (next to notes.js, one level up
// from this file). NOTES_FILE can override the path (used by tests so they never
// touch the real notes.json).
function notesPath() {
  return process.env.NOTES_FILE || path.join(__dirname, '..', 'notes.json');
}

function loadNotes(file = notesPath()) {
  let raw;
  try {
    raw = fs.readFileSync(file, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return [];
    throw err;
  }
  if (raw.trim() === '') return [];
  let data;
  try {
    data = JSON.parse(raw);
  } catch {
    throw new Error(`${file} is not valid JSON; fix or remove it.`);
  }
  if (!Array.isArray(data)) {
    throw new Error(`${file} must contain a JSON array of notes.`);
  }
  return data;
}

function saveNotes(notes, file = notesPath()) {
  // Write to a temp file and rename, so a crash mid-write can't corrupt notes.json.
  const tmp = `${file}.${process.pid}.tmp`;
  fs.writeFileSync(tmp, JSON.stringify(notes, null, 2) + '\n');
  fs.renameSync(tmp, file);
}

// Trim tags, drop empty ones, and remove duplicates (case-insensitively,
// keeping the first spelling given).
function normalizeTags(tags) {
  if (!Array.isArray(tags)) throw new Error('Tags must be an array of strings.');
  const seen = new Set();
  const result = [];
  for (const tag of tags) {
    if (typeof tag !== 'string') throw new Error('Tags must be an array of strings.');
    const t = tag.trim();
    if (t === '' || seen.has(t.toLowerCase())) continue;
    seen.add(t.toLowerCase());
    result.push(t);
  }
  return result;
}

function addNote(text, tags = [], file = notesPath()) {
  if (typeof text !== 'string' || text.trim() === '') {
    throw new Error('Note text cannot be empty.');
  }
  const cleanTags = normalizeTags(tags);
  const notes = loadNotes(file);
  const id = notes.reduce((max, n) => Math.max(max, n.id), 0) + 1;
  const note = { id, text, tags: cleanTags, createdAt: new Date().toISOString() };
  notes.push(note);
  saveNotes(notes, file);
  return note;
}

function listNotes(file = notesPath()) {
  return loadNotes(file);
}

// Case-insensitive substring match against a note's text and each of its tags.
// Notes saved before tags existed have no `tags` field and are treated as untagged.
function searchNotes(query, file = notesPath()) {
  if (typeof query !== 'string' || query.trim() === '') {
    throw new Error('Search term cannot be empty.');
  }
  const q = query.trim().toLowerCase();
  return loadNotes(file).filter(
    (n) =>
      String(n.text).toLowerCase().includes(q) ||
      (n.tags || []).some((t) => t.toLowerCase().includes(q))
  );
}

function deleteNote(id, file = notesPath()) {
  const notes = loadNotes(file);
  const index = notes.findIndex((n) => n.id === id);
  if (index === -1) return null;
  const [removed] = notes.splice(index, 1);
  saveNotes(notes, file);
  return removed;
}

module.exports = {
  notesPath,
  loadNotes,
  saveNotes,
  normalizeTags,
  addNote,
  listNotes,
  searchNotes,
  deleteNote,
};

