'use strict';

// Turning raw command-line arguments into values. No file access or output here.

// Thrown for bad user input; commands.js prints these alongside the usage text.
class UsageError extends Error {}

// Split `add` arguments into note text and tags. Accepts `--tag x` and `--tag=x`;
// anything after a bare `--` is treated as text, so notes can contain "--tag".
function parseAddArgs(args) {
  const words = [];
  const tags = [];
  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg === '--') {
      words.push(...args.slice(i + 1));
      break;
    }
    if (arg === '--tag') {
      const value = args[i + 1];
      if (value === undefined || value.startsWith('--') || value.trim() === '') {
        throw new UsageError('--tag needs a value.');
      }
      tags.push(value);
      i++;
    } else if (arg.startsWith('--tag=')) {
      const value = arg.slice('--tag='.length);
      if (value.trim() === '') throw new UsageError('--tag needs a value.');
      tags.push(value);
    } else if (arg.startsWith('--')) {
      throw new UsageError(`unknown option "${arg}".`);
    } else {
      words.push(arg);
    }
  }
  return { text: words.join(' '), tags };
}

// The search query is all remaining arguments joined by spaces.
function parseSearchArgs(args) {
  return args.join(' ');
}

// A note id must be a non-negative whole number written in digits only.
// Returns the number, or null if the argument is missing or not an id.
function parseId(raw) {
  if (raw === undefined || !/^\d+$/.test(raw)) return null;
  return Number(raw);
}

module.exports = { UsageError, parseAddArgs, parseSearchArgs, parseId };

