'use strict';

// CLI commands: dispatch, validation messages, and output formatting.
// Each command returns the process exit code.

const { addNote, listNotes, searchNotes, deleteNote } = require('./storage.js');
const { UsageError, parseAddArgs, parseSearchArgs, parseId } = require('./parse-args.js');

const USAGE = `Usage:
  node notes.js add "text" [--tag <tag>]...   Add a note, optionally tagged
  node notes.js list                          List all notes
  node notes.js search <word>                 Find notes whose text or tags contain <word>
  node notes.js delete <id>                   Delete a note by id`;

function formatNote(n) {
  const tags = n.tags && n.tags.length ? ` [${n.tags.join(', ')}]` : '';
  return `${n.id}: ${n.text}${tags}`;
}

function cmdAdd(args) {
  let parsed;
  try {
    parsed = parseAddArgs(args);
  } catch (err) {
    if (!(err instanceof UsageError)) throw err;
    console.error(`Error: ${err.message}\n` + USAGE);
    return 1;
  }
  if (parsed.text.trim() === '') {
    console.error('Error: note text is required.\n' + USAGE);
    return 1;
  }
  const note = addNote(parsed.text, parsed.tags);
  console.log(`Added note ${formatNote(note)}`);
  return 0;
}

function cmdList() {
  const notes = listNotes();
  if (notes.length === 0) {
    console.log('No notes.');
  } else {
    for (const n of notes) console.log(formatNote(n));
  }
  return 0;
}

function cmdSearch(args) {
  const query = parseSearchArgs(args);
  if (query.trim() === '') {
    console.error('Error: search needs a word.\n' + USAGE);
    return 1;
  }
  const matches = searchNotes(query);
  if (matches.length === 0) {
    console.log('No matching notes.');
  } else {
    for (const n of matches) console.log(formatNote(n));
  }
  return 0;
}

function cmdDelete(args) {
  const id = parseId(args[0]);
  if (id === null) {
    console.error('Error: delete needs a numeric id.\n' + USAGE);
    return 1;
  }
  const removed = deleteNote(id);
  if (!removed) {
    console.error(`Error: no note with id ${id}.`);
    return 1;
  }
  console.log(`Deleted note ${id}.`);
  return 0;
}

function main(argv) {
  const [command, ...args] = argv;

  switch (command) {
    case 'add':
      return cmdAdd(args);
    case 'list':
      return cmdList();
    case 'search':
      return cmdSearch(args);
    case 'delete':
      return cmdDelete(args);
    case undefined:
    case 'help':
    case '--help':
    case '-h':
      console.log(USAGE);
      return command === undefined ? 1 : 0;
    default:
      console.error(`Error: unknown command "${command}".\n` + USAGE);
      return 1;
  }
}

module.exports = { USAGE, formatNote, main };

