#!/usr/bin/env node
'use strict';

// Entry point. The logic lives in src/:
//   src/storage.js    – notes.json persistence and note operations
//   src/parse-args.js – command-line argument parsing
//   src/commands.js   – CLI commands and output

const storage = require('./src/storage.js');
const { parseAddArgs } = require('./src/parse-args.js');
const { formatNote, main } = require('./src/commands.js');

if (require.main === module) {
  try {
